INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40411, 'Genesis 31:41', 'Genesis', 31, 41, 'په دې ډول زه شل کاله ستا په کور کې وم. څوارلس کاله مې ستا د لورګانو په خاطر ستا خدمت وکړ او شپږ کاله مې ستا د رمو دپاره. لس ځلې دې زما مزدوري بدله کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_41.mp3', '', 1761754199, 1761754199),
(40412, 'Genesis 31:42', 'Genesis', 31, 42, 'که چېرې زما د نیکونو خدای، د ابراهیم او د اسحاق خدای زما سره مل نه وای، نو زه به دې په یقین سره تش لاس لېږلی وای. خو خدای زما سختۍ او د لاسونو خواري ولیدله او تېره شپه یې ملامته کړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_42.mp3', '', 1761754199, 1761754199),
(40413, 'Genesis 31:43', 'Genesis', 31, 43, 'لابان یعقوب ته ځواب ورکړ: «دا ښځې زما لورګانې دي. د هغوی اولادونه زما اولادونه دي او دا رمې زما رمې دي او دا هرڅه چې دلته وینې زما دي. خو زه ستا څخه خپلې لورګانې او د هغوی اولادونه نه شم اخیستلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_43.mp3', '', 1761754199, 1761754199),
(40414, 'Genesis 31:44', 'Genesis', 31, 44, 'زه تیار یم چې ستا سره یو تړون وکړم. راځئ چې د تیږو یوه ډېرۍ جوړه کړو چې مونږ ته به زمونږ تړون رایادوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_44.mp3', '', 1761754199, 1761754199),
(40415, 'Genesis 31:45', 'Genesis', 31, 45, 'نو یعقوب تیږه راواخیستله او هغه یې د یادګار په توګه ودروله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_45.mp3', '', 1761754199, 1761754199),
(40416, 'Genesis 31:46', 'Genesis', 31, 46, 'هغه خپلو خپلوانو ته وویل چې تیږې راټولې کړي. نو هغوی تیږې راواخیستلې او ډېرۍ یې کړې. بیا یعقوب او لابان د هغې ډېرۍ په څنګ کې سره ډوډۍ وخوړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_46.mp3', '', 1761754199, 1761754199),
(40417, 'Genesis 31:47', 'Genesis', 31, 47, 'لابان په هغه باندې یجر سهدوتا نوم کېښود. خو یعقوب هغه د جلعید په نوم یاد کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_47.mp3', '', 1761754199, 1761754199),
(40418, 'Genesis 31:48', 'Genesis', 31, 48, 'لابان وویل: «دا د تیږو ډېرۍ به زمونږ دواړو دپاره یو یادګار وي.» په دې خاطر هغه د جلعید په نوم یاده شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_48.mp3', '', 1761754199, 1761754199),
(40419, 'Genesis 31:49', 'Genesis', 31, 49, 'همدارنګه هغه د مصفه په نوم هم یاده شوه، ځکه چې لابان وویل: «کله چې مونږ یو د بل څخه بېل شو، نو څښتن دې زمونږ دواړو ناظر اوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_49.mp3', '', 1761754199, 1761754199),
(40420, 'Genesis 31:50', 'Genesis', 31, 50, 'که ته زما د لورګانو سره بد چلند وکړې او یا نورې ښځې وکړې، حتی که زه له دې څخه خبر هم نه شم، نو یاد ساته چې خدای زما او ستا ترمنځ شاهد دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_50.mp3', '', 1761754199, 1761754199),
(40421, 'Genesis 31:51', 'Genesis', 31, 51, 'همدارنګه لابان یعقوب ته وویل: «دا هغه ډېرۍ او هغه یادګاري تیږه ده چې زما او ستا ترمنځ مې ودرولې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_51.mp3', '', 1761754199, 1761754199),
(40422, 'Genesis 31:52', 'Genesis', 31, 52, 'دا ډېرۍ او دا تیږه دواړه زمونږ دپاره د یادګار په توګه دي. زه به د دې ډېرۍ څخه ستا خواته نه درتېرېږم چې حمله درباندې وکړم او ته به د دې ډېرۍ او د دې تیږې څخه نه راتېرېږې چې حمله راباندې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_52.mp3', '', 1761754199, 1761754199),
(40423, 'Genesis 31:53', 'Genesis', 31, 53, 'د ابراهیم او د ناحور خدای به زمونږ ترمنځ قضاوت کوي.» بیا یعقوب د هغه خدای په نوم چې د هغه پلار اسحاق ورته عبادت کاوه، سخت قسم وخوړ چې په دې وعدې باندې به ودریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_53.mp3', '', 1761754199, 1761754199),
(40424, 'Genesis 31:54', 'Genesis', 31, 54, 'یعقوب هلته په هغې غرنۍ سیمه کې قرباني وکړه او خپل خپلوان یې ډوډۍ خوړلو ته راوبلل. د ډوډۍ خوړلو څخه وروسته هغوی هلته شپه تېره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_54.mp3', '', 1761754199, 1761754199),
(40425, 'Genesis 31:55', 'Genesis', 31, 55, 'لابان سهار وختي پاڅېد، خپل لمسیان او لورګانې یې ښکل کړل، خدای پاماني یې ورسره وکړه او بېرته خپل کور ته روان شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis31_verse_55.mp3', '', 1761754199, 1761754199),
(40426, 'Amos 9:1', 'Amos', 9, 1, 'ما ولیدل چې څښتن د قربانۍ د ځای سره ولاړ ؤ. هغه حکم وکړ: «د عبادتځای د ستنو سرونه دومره وټکوه چې ټول بنیادونه یې ولړزیږي. هغه ټوټې ټوټې کړه چې د خلکو په سرونو باندې راولویږي. پاتې خلک به زه په جنګ کې ووژنم. هېڅوک به ونه شي تښتېدلی او هېڅوک به خلاص نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_1.mp3', '', 1761754199, 1761754199),
(40427, 'Amos 9:2', 'Amos', 9, 2, 'که هغوی ځمکه وکني او لاندې د مړو دنیا ته هم کوز شي، نو زه به یې راونیسم. که هغوی اسمان ته هم وخېژي، نو زه به یې لاندې راښکته کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_2.mp3', '', 1761754199, 1761754199),
(40428, 'Amos 9:3', 'Amos', 9, 3, 'که هغوی د کرمل د غره په سر هم پټ شي، زه به یې ولټوم او راګېر به یې کړم. که هغوی د بحیرې په تل کې هم زما نه پټ شي، زه به د بحیرې مار ته حکم وکړم چې هغوی وچیچي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_3.mp3', '', 1761754199, 1761754199),
(40429, 'Amos 9:4', 'Amos', 9, 4, 'که هغوی د خپلو دښمنانو له خوا اسیران هم شي، زه به حکم وکړم چې هغوی ووژل شي. ما پرېکړه کړې ده چې د هغوی سره مرسته ونه کړم، بلکې هغوی له منځه یوسم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_4.mp3', '', 1761754199, 1761754199),
(40430, 'Amos 9:5', 'Amos', 9, 5, 'لاس به وروړي مطلق قادر څښتن تعالی ځمکې ته او هغه به وښوییږي څوک چې اوسیږي هلته نو ټول به شروع کړي ماتم ټوله دنیا به پورته کیږي او رالویږي د نیل د سیند په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_5.mp3', '', 1761754199, 1761754199),
(40431, 'Amos 9:6', 'Amos', 9, 6, 'جوړوي په اسمانونو کې خپل کور څښتن او په ځمکه یې ودروله د اسمان ګنبده هغه راوغوښتلې د بحیرې اوبه او ویې بهولې په ځمکه باندې لکه سیلاب په شان د هغه نوم دی څښتن!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_6.mp3', '', 1761754199, 1761754199),
(40432, 'Amos 9:7', 'Amos', 9, 7, 'څښتن داسې وایي: «ای د اسراییلو خلکو، څومره چې زه د ایتوپیا د خلکو په هکله فکر کوم، دومره ستاسو په هکله هم کوم. لکه څنګه چې ما فلسطینیان د کریت نه او د سوریې خلک د قیر نه راوویستل، همداسې مې تاسو هم د مصر نه راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_7.mp3', '', 1761754199, 1761754199),
(40433, 'Amos 9:8', 'Amos', 9, 8, 'زه څښتن تعالی د اسراییلو ګناهکاره پاچاهي وینم او هغه به د ځمکې د مخ نه ورکه کړم. خو د یعقوب ټوله اولاده به له منځه نه وړم.» دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_8.mp3', '', 1761754199, 1761754199),
(40434, 'Amos 9:9', 'Amos', 9, 9, 'نو ګورئ، زه به حکم وکړم او د اسراییلو خلک به داسې غلبېل کړم لکه غله چې په غلبیل کې خوځیږي. کله چې هغوی د نورو قومونو په منځ کې اوسیږي، زه به یې داسې غلبیل کړم چې بد خلک لکه د تیږو په شان ورڅخه لېرې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_9.mp3', '', 1761754199, 1761754199),
(40435, 'Amos 9:10', 'Amos', 9, 10, 'زما په قوم کې چې کوم خلک ګناهکار دي، هغه به په جنګ کې ووژل شي، یعنې هغه ټول خلک چې وایي: «په مونږ به کوم مصیبت نه راځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_10.mp3', '', 1761754199, 1761754199),
(40436, 'Amos 9:11', 'Amos', 9, 11, 'څښتن وایي: «یوه داسې ورځ راروانه ده چې زه به د داود پاچاهي چې لکه د یو کور په شان ورانه شوې وه، بېرته جوړه کړم. زه به د هغه دېوالونه بېرته جوړ کړم او هغه کنډوالې به بېرته ابادې کړم او زه به هغه د پخوا په شان بېرته ودان کړم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_11.mp3', '', 1761754199, 1761754199),
(40437, 'Amos 9:12', 'Amos', 9, 12, 'ترڅو د اسراییلو خلک به هغه څه چې په ادوم کې پاتې دي او هغه ټول قومونه چې په یو وخت کې زما وو، ونیسي.» څښتن وایي چې همداسې به وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_12.mp3', '', 1761754199, 1761754199),
(40438, 'Amos 9:13', 'Amos', 9, 13, 'څښتن داسې وایي: راروان دی هغه وخت چې فصلونه به پخیږي د رېبلو وخت نه مخکې او پخیږي به انګور د شرابو جوړېدو نه مخکې او له غونډیو راتوییږي به', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_13.mp3', '', 1761754199, 1761754199),
(40439, 'Amos 9:14', 'Amos', 9, 14, 'زه به راولم خپل قوم بېرته خپل وطن ته بېرته اباد به کړي دوی خپل کنډوالې ښارونه او په کې اوسیږي به هغوی به وکري باغونه د انګورو او شراب به یې څښي هغوی به وکري باغونه او مېوه به یې خوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_14.mp3', '', 1761754199, 1761754199),
(40440, 'Amos 9:15', 'Amos', 9, 15, 'زه به وکرم خپل قوم هغه وطن کې او ویستلی به بیا نه شي هغوی له هغه وطنه چې ورکړی مې دی دا هغه څه دي چې څښتن، ستاسو خدای ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos9_verse_15.mp3', '', 1761754199, 1761754199),
(40441, 'Isaiah 3:1', 'Isaiah', 3, 1, 'اوس څښتن، مطلق قادر څښتن به د اورشلیم او یهودا نه ټول شیان چې د خلکو ژوند ورسره تړلي دي، واخلي. هغه به د خوړو او اوبو قحطي راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_1.mp3', '', 1761754199, 1761754199),
(40442, 'Isaiah 3:2', 'Isaiah', 3, 2, 'څښتن به د هغوی جنګیالیان او د هغوی عسکر، د هغوی قاضیان او پیغمبران، د هغوی فال کتونکي او سپین ږیري،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_2.mp3', '', 1761754199, 1761754199),
(40443, 'Isaiah 3:3', 'Isaiah', 3, 3, 'د هغوی نظامي او ملکي مشران، د هغوی مشاوران، ماهر کسبګران او جادوګران، هم واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_3.mp3', '', 1761754199, 1761754199),
(40444, 'Isaiah 3:4', 'Isaiah', 3, 4, 'څښتن به هلکان د هغوی مشران کړي او ماشومان به په هغوی باندې حکومت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_4.mp3', '', 1761754199, 1761754199),
(40445, 'Isaiah 3:5', 'Isaiah', 3, 5, 'خلک به په یو بل باندې ظلم او زیاتی کوي. ځوانان به د خپلو مشرانو سپکاوی کوي او سپک خلک به د شریفو خلکو عزت نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_5.mp3', '', 1761754199, 1761754199),
(40446, 'Isaiah 3:6', 'Isaiah', 3, 6, 'داسې وخت به راشي چې د یوې طایفې خلک به د خپل منځ نه یو کس خوښ کړي او هغه ته به ووایي: «ته خو یوه چپنه لرې، راشه د دې کنډوالې مشر شه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_6.mp3', '', 1761754199, 1761754199),
(40447, 'Isaiah 3:7', 'Isaiah', 3, 7, 'خو هغه به په ټینګه ځواب ورکړي: «نه! زه ستاسو سره مرسته نه شم کولای. زما سره نه خواړه شته او نه چپنه. ما د خپل مشر په توګه مه ټاکئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_7.mp3', '', 1761754199, 1761754199),
(40448, 'Isaiah 3:8', 'Isaiah', 3, 8, 'هو، اورشلیم تباه کیږي! او یهودا سقوط کوي! هغوی چې هرڅه وایي او هرڅه کوي هغه د څښتن په خلاف دي. هغوی د هغه د جلال په وړاندې سرکښي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_8.mp3', '', 1761754199, 1761754199),
(40449, 'Isaiah 3:9', 'Isaiah', 3, 9, 'د هغوی د مخونو څخه د هغوی ملامتیا ښکاره ده. هغوی د سدوم د خلکو په شان په ښکاره ګناه کوي. افسوس د هغوی په حال! ځکه هغوی په خپله دا تباهي په خپل ځان باندې راوستې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_9.mp3', '', 1761754199, 1761754199),
(40450, 'Isaiah 3:10', 'Isaiah', 3, 10, 'نېکو خلکو ته ووایئ: «ستاسو هر کار به سم روان وي. تاسو به د خپل کار او زحمت ثمره ووینئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_10.mp3', '', 1761754199, 1761754199),
(40451, 'Isaiah 3:11', 'Isaiah', 3, 11, 'بدو خلکو ته ووایئ: «افسوس ستاسو په حال! ځکه ستاسو سره به د بدو کارونو په بدل کې عمل وشي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_11.mp3', '', 1761754199, 1761754199),
(40452, 'Isaiah 3:12', 'Isaiah', 3, 12, 'ماشومان زما په قوم باندې ظلم کوي او ښځې په هغوی باندې حکومت کوي. ای زما قومه، ستاسو مشران تاسو بې لارې کوي، نه غواړي چې تاسو په سمه لاره لاړ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_12.mp3', '', 1761754199, 1761754199),
(40453, 'Isaiah 3:13', 'Isaiah', 3, 13, 'څښتن دې ته تیار دی چې خپله محاکمه دایره کړي او د خلکو قضاوت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_13.mp3', '', 1761754199, 1761754199),
(40454, 'Isaiah 3:14', 'Isaiah', 3, 14, 'څښتن د خپل قوم سپین ږیري او مشران د محاکمې دپاره راولي. هغوی ته وایي: «تاسو زما د انګورو باغ لوټ کړی دی او د غریبانو څخه مو چې هرڅه وړي دي، د هغو څخه مو خپل کورونه ډک کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_14.mp3', '', 1761754199, 1761754199),
(40455, 'Isaiah 3:15', 'Isaiah', 3, 15, 'تاسو حق نه لرئ چې زما قوم تر پښو لاندې کړئ او د غریبانو سرونه په ځمکه ووهئ. زه مطلق قادر څښتن خدای داسې وایم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_15.mp3', '', 1761754199, 1761754199),
(40456, 'Isaiah 3:16', 'Isaiah', 3, 16, 'څښتن وویل: «وګورئ، د اورشلیم ښځې څومره مغرورې دي! هغوی هسکې غاړې نیولې او روانې دي. هغوی د شهوت په سترګو هرې خواته ګوري. په ناز او نخرو باندې قدمونه اخلي او خپل پایزیبونه شرنګوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_16.mp3', '', 1761754199, 1761754199),
(40457, 'Isaiah 3:17', 'Isaiah', 3, 17, 'خو زه به هغوی ته سزا ورکړم - د هغوی سرونه به وخرایم او هغوی به بې پردې او رسوا کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_17.mp3', '', 1761754199, 1761754199),
(40458, 'Isaiah 3:18', 'Isaiah', 3, 18, 'داسې ورځ راورانه ده چې څښتن به د اورشلیم د ښځو څخه هغه ټول شیان چې هغوی ورباندې مغروره دي، اخلي، یعنې: د هغوی پایزیبونه، د سر ټیک، د نوې میاشتې د سپوږمۍ په شان غاړکۍ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_18.mp3', '', 1761754199, 1761754199),
(40459, 'Isaiah 3:19', 'Isaiah', 3, 19, 'غوږوالۍ، بنګړي او نقابونه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_19.mp3', '', 1761754199, 1761754199),
(40460, 'Isaiah 3:20', 'Isaiah', 3, 20, 'ټیکري، بازوبندونه، کمربندونه، د عطرو بوتلونه او تعویذونه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_20.mp3', '', 1761754199, 1761754199),
(40461, 'Isaiah 3:21', 'Isaiah', 3, 21, 'ګوتې او پېزوانونه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_21.mp3', '', 1761754199, 1761754199),
(40462, 'Isaiah 3:22', 'Isaiah', 3, 22, 'ښکلې چپنې، بې لستوڼو چپنې، شالونه، لاسي بکسونه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_22.mp3', '', 1761754199, 1761754199),
(40463, 'Isaiah 3:23', 'Isaiah', 3, 23, 'آئینې، د کتان کالي، تاجونه او څادرونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_23.mp3', '', 1761754199, 1761754199),
(40464, 'Isaiah 3:24', 'Isaiah', 3, 24, 'د عطرو په ځای به د هغوی نه بد بوی خېژي، د ښایسته کمربندونو په ځای به هغوی زیږه پړي له ځانه راتاو کړي وي، د ښایسته ویښتانو په ځای به هغوی ګنجیانې وي، د ښکلو جامو په ځای به هغوی بدرنګې جامې اغوستې وي، د هغوی ښایست به د شرم په داغ بدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_24.mp3', '', 1761754199, 1761754199),
(40465, 'Isaiah 3:25', 'Isaiah', 3, 25, 'د ښار سړي به په توره او ستاسو تکړه سړي به د جګړې په ډګر کې ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_25.mp3', '', 1761754199, 1761754199),
(40466, 'Isaiah 3:26', 'Isaiah', 3, 26, 'د ښار د دروازو څخه به د ژړا او ویر اوازونه اورېدل کیږي او خپله ښار به په ماتم کې ویجاړیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah3_verse_26.mp3', '', 1761754199, 1761754199),
(40467, 'Esther 10:1', 'Esther', 10, 1, 'خشایار پاچا په خپلې امپراتورۍ کې هر یو دې ته مجبور کړ چې باج ورکړي، حتی هغه خلک چې د جزیرو څخه لېرې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther10_verse_1.mp3', '', 1761754199, 1761754199),
(40468, 'Esther 10:2', 'Esther', 10, 2, 'هغه ټول لوی او عجیبه کارونه چې خشایار پاچا کړي وو او هغه پوره کیسه چې هغه څنګه مردخای ته لوړ مقام ورکړ، هغه د ماد او فارس د پاچاهانو د تاریخ په کتاب کې لیکل شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther10_verse_2.mp3', '', 1761754199, 1761754199),
(40469, 'Esther 10:3', 'Esther', 10, 3, 'یهودي مردخای د خشایار پاچا څخه وروسته دوهم کس ؤ. یهودیانو هغه ته په درنه سترګه کتل او ورباندې ګران ؤ. هغه د خپلو خلکو د ښېګڼې او د هغوی د ټولې اولادې د ارامۍ دپاره غږ پورته کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther10_verse_3.mp3', '', 1761754199, 1761754199),
(40470, 'Isaiah 33:1', 'Isaiah', 33, 1, 'افسوس ستاسو په حال چې خلک تباه کوئ او خیانت کوئ، که څه هم تاسو تباه او برباد شوي نه یئ او نه ستاسو سره خیانت شوی دی. ستاسو د تباهۍ او خیانت وخت به پای ته ورسیږي او هغه وخت به راورسیږي چې تاسو د تباهۍ او خیانت ښکار شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_1.mp3', '', 1761754199, 1761754199),
(40471, 'Isaiah 33:2', 'Isaiah', 33, 2, 'ای څښتنه، په مونږ رحم وکړه. زمونږ هیله تاته ده. هر سهار مونږ ته قوت راکړه او د کړاوونو په وخت کې زمونږ ژغورونکی شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_2.mp3', '', 1761754199, 1761754199),
(40472, 'Isaiah 33:3', 'Isaiah', 33, 3, 'کله چې دښمن ستا د تندر په شان اواز اوري، نو تښتي. ستا له پاڅېدو سره قومونه خواره واره کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_3.mp3', '', 1761754199, 1761754199),
(40473, 'Isaiah 33:4', 'Isaiah', 33, 4, 'زمونږ د دښمنانو شتمني به داسې لوټ او تالا شي، لکه ملخان چې په کروندو باندې حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_4.mp3', '', 1761754199, 1761754199),
(40474, 'Isaiah 33:5', 'Isaiah', 33, 5, 'څښتن څومره لوی دی. هغه په اسمان کې اوسیږي. هغه به صهیون د عدالت او انصاف څخه ډک کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_5.mp3', '', 1761754199, 1761754199),
(40475, 'Isaiah 33:6', 'Isaiah', 33, 6, 'او ستاسو دپاره به یو ټینګ بنیاد وي. هغه به تل تاسو وژغوري او تاسو ته به ډېر حکمت او ډېره پوهه درکړي. د څښتن څخه وېره د صهیون دپاره د خزانې په شان ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_6.mp3', '', 1761754199, 1761754199),
(40476, 'Isaiah 33:7', 'Isaiah', 33, 7, 'واورئ! زړور خلک په کوڅو کې د مرستې دپاره چیغې وهي. د سولې استازي اوس په چیغو چیغو ژاړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_7.mp3', '', 1761754199, 1761754199),
(40477, 'Isaiah 33:8', 'Isaiah', 33, 8, 'لویي لارې دومره له خطره ډکې شوې دي چې هېڅوک ورباندې سفر نه شي کولای. خلکو تړونونه مات کړي دي او هغه وعدې چې د شاهدانو په وړاندې یې کړې وې، نه دي عملي کړې. هغوی نور د هېچا درناوی نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_8.mp3', '', 1761754199, 1761754199),
(40478, 'Isaiah 33:9', 'Isaiah', 33, 9, 'د اسراییلو ځمکه وچه او شاړه پرته ده. د لبنان ځنګلونه وچ شوي دي. د شارون حاصلخېزه دره لکه د دښتې په شان شوې ده. د باشان او د کرمل د ونو پاڼې رالویږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_9.mp3', '', 1761754199, 1761754199),
(40479, 'Isaiah 33:10', 'Isaiah', 33, 10, 'څښتن قومونو ته وایي: «اوس پاڅېږم. زه به تاسو ته خپل قدرت او لویي وښایم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_10.mp3', '', 1761754199, 1761754199),
(40480, 'Isaiah 33:11', 'Isaiah', 33, 11, 'ستاسو نقشې بې ارزښته دي او هرڅه چې کوئ هغه بې ګټې دي. ستاسو نفس به په اور بدل شي، تاسو به په خپله وسوځوي او له منځه به مو یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_11.mp3', '', 1761754199, 1761754199),
(40481, 'Isaiah 33:12', 'Isaiah', 33, 12, 'تاسو به لکه د اغزیو د بوټو په شان په اور کې وغورځول شئ، وبه سوځئ او په ایرو به بدل شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_12.mp3', '', 1761754199, 1761754199),
(40482, 'Isaiah 33:13', 'Isaiah', 33, 13, 'ای لرې او نژدې خلکو، څه چې مې تر سره کړي، هغه ته پام وکړئ او زما قدرت ومنئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_13.mp3', '', 1761754199, 1761754199),
(40483, 'Isaiah 33:14', 'Isaiah', 33, 14, 'د صهیون ګناهکاران وېرېږي، بې ایمانه خلک رپیږي او وایي: «د خدای قضاوت د یو تباه کوونکي اور په شان دی. څوک به زمونږ څخه په داسې تل بلېدونکي اور کې ژوندی پاتې شي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_14.mp3', '', 1761754199, 1761754199),
(40484, 'Isaiah 33:15', 'Isaiah', 33, 15, 'هغه څوک ژوندی پاتې کېدای شي چې په خپل ژوند کې نېک وي او رښتیا وایي، د غریبانو د غولولو دپاره د خپل زور څخه کار وانخلي او د رشوت اخیستلو څخه لاس واخلي، د قتل په نقشو کې برخه وانخلي او د بدۍ څخه هم ځان وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_15.mp3', '', 1761754199, 1761754199),
(40485, 'Isaiah 33:16', 'Isaiah', 33, 16, 'داسې کسان به په امن کې ژوند کوي او هغوی به داسې په امن کې اوسیږي لکه څنګه چې څوک د تیږو په کلاګانو کې اوسیږي. هغوی ته به خواړه ورکړل شي او بې له شکه به اوبه ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_16.mp3', '', 1761754199, 1761754199),
(40486, 'Isaiah 33:17', 'Isaiah', 33, 17, 'تاسو به د پاچا هغه شان او شوکت ووینئ چې په یو لوی او پراخ هېواد پاچاهي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_17.mp3', '', 1761754199, 1761754199),
(40487, 'Isaiah 33:18', 'Isaiah', 33, 18, 'بیا به د تېر شوي ظلم په اړه فکر وکړئ، له خپل ځانه به پوښتنه وکړئ او وبه وایئ: «هغه پردي مامورین چېرته دي چې زمونږ نه به یې باج اخیسته؟ هغه جاسوسان چېرته دي چې زمونږ برجونه به یې شمېرل؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_18.mp3', '', 1761754199, 1761754199),
(40488, 'Isaiah 33:19', 'Isaiah', 33, 19, 'خو تاسو به نور د هغه پردي هېواد کبرجن خلک ونه وینئ چې په پردۍ ژبه یې خبرې کولې او تاسو د هغه په معنی نه پوهېدلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_19.mp3', '', 1761754199, 1761754199),
(40489, 'Isaiah 33:20', 'Isaiah', 33, 20, 'صهیون ته وګورئ، یعنې هغه ښار ته چې مونږ په کې خپل دیني اخترونه لمانځو. تاسو به اورشلیم ووینئ چې هغه د اوسېدلو دپاره څنګه خوندي ځای دی. اورشلیم به د هغې خېمې په شان وي چې نه خوځیږي او موږي به یې هېڅکله راونه ویستل شي او رسۍ به یې هېڅکله ونه شلیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_20.mp3', '', 1761754199, 1761754199),
(40490, 'Isaiah 33:21', 'Isaiah', 33, 21, 'هلته به زمونږ د جلال څخه ډک څښتن د لویو سیندونو او ویالو په شان زمونږ څخه ساتنه وکړي او نور به د دښمن کشتۍ ونه شي کولای د هغه نه تېرې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_21.mp3', '', 1761754199, 1761754199),
(40491, 'Isaiah 33:22', 'Isaiah', 33, 22, 'څښتن په خپله زمونږ قاضي، حکم ورکوونکی او پاچا دی او هغه به مونږ وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_22.mp3', '', 1761754199, 1761754199),
(40492, 'Isaiah 33:23', 'Isaiah', 33, 23, 'د دښمن د کشتۍ ګانو طنابونه او رسۍ به سستې شي، نه به یې ستنې ټینګې شي او نه به یې بادوانونه خلاص شي. د دښمن د لښکرو ټول مالونه به د غنیمت په توګه ووېشل شي او دا مال به دومره ډېر وي چې ګوډانو ته به هم په کې خپله برخه ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_23.mp3', '', 1761754199, 1761754199),
(40493, 'Isaiah 33:24', 'Isaiah', 33, 24, 'زمونږ د وطن اوسېدونکي به هېڅکله دا شکایت ونه کړي: «زه ناروغ یم» او د هغوی ټول ګناهونه به وبخښل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah33_verse_24.mp3', '', 1761754199, 1761754199),
(40494, 'Job 5:1', 'Job', 5, 1, 'آواز وکړه، داسې څوک شته چې تا له جواب درکړى؟ داسې يوه فرښته شته څۀ چې د هغې نه مدد وغواړې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_1.mp3', '', 1761754199, 1761754199),
(40495, 'Job 5:2', 'Job', 5, 2, 'په حقيقت کښې نفرت کم عقل خلق وژنى، او حسد ساده خلق وژنى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_2.mp3', '', 1761754199, 1761754199),
(40496, 'Job 5:3', 'Job', 5, 3, 'ما دا ليدلى دى چې څۀ کم عقل خلق د لږ وخت دپاره کامياب وى، خو بيا ناڅاپه تباهى ورباندې راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_3.mp3', '', 1761754199, 1761754199),
(40497, 'Job 5:4', 'Job', 5, 4, 'د هغوئ د بچو دپاره به د پناه هيڅ امکان نۀ وى، او داسې به څوک نۀ وى چې په عدالت کښې يې خلاص کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_4.mp3', '', 1761754199, 1761754199),
(40498, 'Job 5:5', 'Job', 5, 5, 'اوږى خلق د کم عقلو فصلونه خورى، کۀ د هغۀ د پټو نه د حِفاظت دپاره ازغى هم تاو وى، لالچى خلق د هغوئ دولت ختم کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_5.mp3', '', 1761754199, 1761754199),
(40499, 'Job 5:6', 'Job', 5, 6, 'ځکه چې خفګان د زمکې نه نۀ راځى، او نۀ مصيبت د زمکې نه پېدا کيږى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_6.mp3', '', 1761754199, 1761754199),
(40500, 'Job 5:7', 'Job', 5, 7, 'خو انسانان د مصيبت دپاره داسې پېدا شوى دى لکه چې د اور بڅرکى بره الوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_7.mp3', '', 1761754199, 1761754199),
(40501, 'Job 5:8', 'Job', 5, 8, 'کۀ زۀ ستا په ځائ وے نو ما به خُدائ پاک لټولے، او خُدائ پاک ته به مې فرياد اورولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_8.mp3', '', 1761754199, 1761754199),
(40502, 'Job 5:9', 'Job', 5, 9, 'هغه داسې لوئ لوئ کارونه کوى چې څوک ورباندې نۀ پوهيږى، هغه بې‌شمېره عجيبه کارونه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_9.mp3', '', 1761754199, 1761754199),
(40503, 'Job 5:10', 'Job', 5, 10, 'هغه په زمکه باندې باران ورَوى او هغه پټو ته اوبۀ رالېږى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_10.mp3', '', 1761754199, 1761754199),
(40504, 'Job 5:11', 'Job', 5, 11, 'چې څوک غريب وى نو خُدائ پاک يې مالداره کړى، او چې څوک غمژن وى نو خوشحالى ورکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_11.mp3', '', 1761754199, 1761754199),
(40505, 'Job 5:12', 'Job', 5, 12, 'هغه د چالاکو منصوبې ګډې وډې کړى، نو داسې د هغوئ په لاس کښې هيڅ کاميابى نۀ راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_12.mp3', '', 1761754199, 1761754199),
(40506, 'Job 5:13', 'Job', 5, 13, 'هغه هوښيار د خپلې چالاکۍ په جال کښې راګېروى، او چالاک خلق زر فنا شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_13.mp3', '', 1761754199, 1761754199),
(40507, 'Job 5:14', 'Job', 5, 14, 'د ورځې په وخت په هغوئ تيارۀ راشى او د غرمې په وخت داسې تيندکونه خورى لکه چې شپه وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_14.mp3', '', 1761754199, 1761754199),
(40508, 'Job 5:15', 'Job', 5, 15, 'خو هغه ضرورتمند خلق د مرګ نه بچ کوى، او د زورَور د زور نه يې بچ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_15.mp3', '', 1761754199, 1761754199),
(40509, 'Job 5:16', 'Job', 5, 16, 'نو چې غريبانان اُميد ولرى، او د بې‌اِنصافه خلقو خولې بندې کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_16.mp3', '', 1761754199, 1761754199),
(40510, 'Job 5:17', 'Job', 5, 17, 'چې خُدائ پاک څوک ټيک کړى نو هغوئ څومره خوشحاله وى، نو په دې وجه د قادر خُدائ تربيت ته سپک مۀ ګورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job5_verse_17.mp3', '', 1761754199, 1761754199);